.rainbow-btn {
  padding: 18px 50px; font-size: 20px; font-weight: 900; border: none;
  border-radius: 50px; cursor: pointer; color: white;
  background: linear-gradient(90deg, #ff4757, #ffa502, #2ed573, #1e90ff, #3742fa, #ff4757);
  background-size: 300%; animation: rainbowBG 4s linear infinite;
  box-shadow: 0 10px 20px rgba(0,0,0,0.15); 
  transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275), box-shadow 0.4s;
  font-family: sans-serif; letter-spacing: 2px;
}
.rainbow-btn:hover { 
  transform: scale(1.15) translateY(-5px); 
  box-shadow: 0 20px 30px rgba(0,0,0,0.2); 
}
.rainbow-btn:active {
  transform: scale(0.95); box-shadow: 0 5px 10px rgba(0,0,0,0.1);
}
@keyframes rainbowBG { 0% { background-position: 0% 50%; } 100% { background-position: 100% 50%; } }

